import React, { useState, useEffect } from "react";
import { useHistory, useParams } from "react-router-dom";
import { updateCar } from "../../services/ApiCar";

export default function CardEditVoiture() {
  const history = useHistory();
  const { idCar } = useParams(); // Récupère l'ID depuis l'URL
  const [carData, setCarData] = useState({
    matricule: "",
    model: "",
    marque: "",
    libelle: "",
    prix: "",
    prix_jour: "",
    couleur: "",
    disponible: false,
    voiture_image: null,
  });
  const [errors, setErrors] = useState({});

  // Charger les données existantes de la voiture (à implémenter)
  useEffect(() => {
    // Fonction pour charger les données existantes
    const fetchCarData = async () => {
      try {
        // const response = await getCarById(idCar);
        // setCarData(response.data);
      } catch (error) {
        console.error("Erreur lors du chargement:", error);
      }
    };
    
    fetchCarData();
  }, [idCar]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setCarData({ ...carData, [name]: value });
  };

  const handleFileChange = (e) => {
    setCarData({ ...carData, voiture_image: e.target.files[0] });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Validation des champs
    let formErrors = {};
    if (!carData.matricule.trim()) formErrors.matricule = "Matricule requis";
    if (!carData.model.trim()) formErrors.model = "Modèle requis";
    // Ajoutez les autres validations nécessaires...

    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      return;
    }

    try {
      // Création du FormData
      const formData = new FormData();
      Object.keys(carData).forEach(key => {
        if (carData[key] !== null) {
          formData.append(key, carData[key]);
        }
      });

      // Appel à l'API de mise à jour
      await updateCar(formData, idCar);
      
      // Redirection après succès
      history.push("/admin/cardvoiture");
    } catch (error) {
      console.error("Erreur lors de la mise à jour:", error);
      alert("Erreur lors de la mise à jour de la voiture");
    }
  };

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
      {/* Entête */}
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-blueGray-700 text-xl font-bold">Modifier la voiture</h6>
          <button
            className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow hover:shadow-md"
            type="button"
            onClick={() => history.push("/admin/cardvoiture")}
          >
            Retour
          </button>
        </div>
      </div>

      {/* Formulaire */}
      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        <form onSubmit={handleSubmit}>
          {/* Les champs du formulaire (similaires à CardAddVoiture) */}
          {/* ... */}

          <div className="text-center mt-6">
            <button
              type="submit"
              className="bg-green-500 text-white active:bg-green-600 font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md outline-none focus:outline-none mr-1 ease-linear transition-all duration-150"
            >
              Mettre à jour
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
